// flutter_cumulative_results_screen.dart
// Mirrors cumulative_results.php 1:1:
//  • school card, "Generate Result Sheet" filters (Class / Session / Term required, Department optional)
//  • stats: Total Students, Subjects, Pass Rate, Class Average
//  • result table: sticky # + Student Name, ID No., one column per subject (score/60, %, grade chip),
//    Total, Avg (with bar), Pos. (gold / silver / bronze badges), Grade Key legend
//  • PDF (built on the phone, same layout/paper-size rules as the web jsPDF export)
//  • Excel (.xlsx generated by flutter_cumulative_results.php, opened as a download)
//
// pubspec.yaml needs:  http, shared_preferences, url_launcher, pdf, printing
//   flutter pub add pdf printing url_launcher
// API: https://schoolsmirror.com/flutter_cumulative_results.php

import 'dart:async';
import 'dart:convert';
import 'dart:math' as math;
import 'dart:typed_data';
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;
import 'package:pdf/pdf.dart';
import 'package:pdf/widgets.dart' as pw;
import 'package:printing/printing.dart';
import 'package:shared_preferences/shared_preferences.dart';
import 'package:url_launcher/url_launcher.dart';
import '../api/api_client.dart';

// Your host redirects "*.php" to the extensionless address and a redirect turns POST into GET
// (form data lost -> "Missing token"). The extensionless URL is tried first; the app switches to
// the other form automatically if one of them fails.
const List<String> _apiUrls = [
  'https://schoolsmirror.com/flutter_cumulative_results',
  'https://schoolsmirror.com/flutter_cumulative_results.php',
];
int _apiIdx = 0;
String get _apiUrl => _apiUrls[_apiIdx];

// ---- :root tokens of the web page ----
const Color _navy = Color(0xFF0A1628);
const Color _navy2 = Color(0xFF122040);
const Color _blue = Color(0xFF1B4FD8);
const Color _blue2 = Color(0xFF2563EB);
const Color _sky = Color(0xFFE8F0FE);
const Color _muted = Color(0xFF94A3B8);
const Color _border = Color(0xFFE2E8F0);
const Color _bg = Color(0xFFF1F5F9);
const Color _text = Color(0xFF0F172A);
const Color _text2 = Color(0xFF475569);
const TextStyle _fieldStyle = TextStyle(fontSize: 14, color: _text);

List<BoxShadow> get _shadow => [
      BoxShadow(color: Colors.black.withOpacity(0.06), blurRadius: 3, offset: const Offset(0, 1)),
      BoxShadow(color: Colors.black.withOpacity(0.07), blurRadius: 24, offset: const Offset(0, 8)),
    ];

/// The app theme can be dark; this page always uses a light theme so text is readable.
ThemeData _lightTheme() {
  final base = ThemeData.light();
  return base.copyWith(
    scaffoldBackgroundColor: _bg,
    canvasColor: Colors.white,
    cardColor: Colors.white,
    colorScheme: base.colorScheme.copyWith(primary: _blue, surface: Colors.white, onSurface: _text),
    textTheme: base.textTheme.apply(bodyColor: _text, displayColor: _text),
  );
}

