// ───────────────────────────── helpers ─────────────────────────────
int _int(dynamic v) => int.tryParse('${v ?? ''}') ?? 0;

/// 45.0 -> "45", 66.7 -> "66.7"  (same as PHP echo of a rounded number)
String _n(dynamic v) {
  final d = double.tryParse('${v ?? ''}') ?? 0;
  return d == d.roundToDouble() ? d.toInt().toString() : d.toString();
}

List<Map<String, dynamic>> _maps(dynamic v) =>
    (v is List ? v : []).map((e) => Map<String, dynamic>.from(e as Map)).toList();

String _friendly(Object e) {
  final s = e.toString();
  if (e is TimeoutException) return 'Request timed out. Please try again.';
  if (e is http.ClientException || s.contains('Failed to fetch') || s.contains('SocketException')) {
    return 'Cannot reach the server. Check your internet connection.';
  }
  return s.replaceFirst('Exception: ', '');
}

class _Api {
  static bool _retry(Map<String, dynamic> d) {
    final m = '${d['message'] ?? ''}';
    return d['success'] != true &&
        (m == 'Unexpected server response' ||
            m.startsWith('The server received this request as') ||
            m.startsWith('Missing token'));
  }

  static Map<String, dynamic> _decode(String body) {
    try {
      final i = body.indexOf('{');
      final d = jsonDecode(i > 0 ? body.substring(i) : body);
      if (d is Map<String, dynamic>) return d;
    } catch (_) {}
    return {'success': false, 'message': 'Unexpected server response'};
  }

  /// token + action + fields are sent in the URL AND the body so they survive a redirect.
  static Future<Map<String, dynamic>> call(String token, String action, [Map<String, String> fields = const {}]) async {
    Object? err;
    for (var i = 0; i < _apiUrls.length; i++) {
      try {
        final uri = Uri.parse(_apiUrl).replace(queryParameters: {'token': token, 'action': action, ...fields});
        final res = await http
            .post(
              uri,
              headers: {'Content-Type': 'application/x-www-form-urlencoded; charset=utf-8'},
              body: {'token': token, 'action': action, ...fields},
            )
            .timeout(const Duration(seconds: 60));
        final d = _decode(res.body);
        if (_retry(d) && _apiIdx < _apiUrls.length - 1) {
          _apiIdx++;
          continue;
        }
        return d;
      } catch (e) {
        err = e;
        if (_apiIdx < _apiUrls.length - 1) {
          _apiIdx++;
          continue;
        }
      }
    }
    throw Exception(_friendly(err ?? 'Request failed'));
  }
}

// ───────────────────────────── SCREEN ─────────────────────────────
class FlutterCumulativeResultsScreen extends StatefulWidget {
  final String? token;
  const FlutterCumulativeResultsScreen({super.key, this.token});

  @override
  State<FlutterCumulativeResultsScreen> createState() => _FlutterCumulativeResultsScreenState();
}

class _FlutterCumulativeResultsScreenState extends State<FlutterCumulativeResultsScreen> {
  String? _token;
  String _schoolName = 'My School';

  int? _classId, _sessionId, _termId;
  int _deptId = 0; // 0 = All Departments
  List<Map<String, dynamic>> _classes = [], _sessions = [], _terms = [], _departments = [];

  bool _loadingData = true;
  String? _dataError;
  bool _generating = false;
  bool _searched = false; // a sheet was requested (to show "No results found")
  bool _pdfBusy = false;
  bool _xlBusy = false;

  // result sheet
  List<Map<String, dynamic>> _results = [];
  List<String> _subjects = [];
  Map<String, dynamic> _stats = {};
  String _classLabel = '', _sessionLabel = '', _termLabel = '';
  List<Map<String, dynamic>> _gradeKey = [];

  final _scroll = ScrollController();
  final _tableKey = GlobalKey();

  @override
  void initState() {
    super.initState();
    _init();
  }

  @override
  void dispose() {
    _scroll.dispose();
    super.dispose();
  }

  Future<String?> _getToken() async {
    if (widget.token != null && widget.token!.trim().isNotEmpty) return widget.token!.trim();
    try {
      await ApiClient.loadToken();
      final t = ApiClient.token;
      if (t != null && t.trim().isNotEmpty) return t.trim();
    } catch (_) {}
    try {
      final p = await SharedPreferences.getInstance();
      final t = p.getString('auth_token') ?? p.getString('token');
      if (t != null && t.trim().isNotEmpty) return t.trim();
    } catch (_) {}
    return null;
  }

  void _toast(String msg, {bool error = false}) {
    if (!mounted) return;
    ScaffoldMessenger.of(context)
      ..hideCurrentSnackBar()
      ..showSnackBar(SnackBar(
        content: Text(msg),
        backgroundColor: error ? const Color(0xFFDC2626) : const Color(0xFF059669),
        behavior: SnackBarBehavior.floating,
      ));
  }

  // ───────────────────────────── data ─────────────────────────────
  Future<void> _init() async {
    setState(() {
      _loadingData = true;
      _dataError = null;
    });
    try {
      _token = await _getToken();
      if (_token == null) throw Exception('Session expired. Please log in again.');
      final r = await _Api.call(_token!, 'load_data');
      if (r['success'] != true) throw Exception(r['message'] ?? 'Failed to load');
      final d = (r['data'] as Map?) ?? {};
      if (!mounted) return;
      setState(() {
        _classes = _maps(d['classes']);
        _sessions = _maps(d['sessions']);
        _terms = _maps(d['terms']);
        _departments = _maps(d['departments']);
        _schoolName = '${d['school_name'] ?? 'My School'}';
        _loadingData = false;
      });
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _dataError = _friendly(e);
        _loadingData = false;
      });
    }
  }

  Future<void> _generate() async {
    if (_classId == null || _sessionId == null || _termId == null) {
      _toast('Please select Class, Session & Term', error: true);
      return;
    }
    setState(() {
      _generating = true;
      _searched = false;
      _results = [];
    });
    try {
      final r = await _Api.call(_token!, 'generate_results', {
        'class_id': '$_classId',
        'session_id': '$_sessionId',
        'term_id': '$_termId',
        if (_deptId > 0) 'department_id': '$_deptId',
      });
      if (r['success'] != true) throw Exception(r['message'] ?? 'Failed to generate results');
      final d = (r['data'] as Map?) ?? {};
      if (!mounted) return;
      setState(() {
        _schoolName = '${d['school_name'] ?? _schoolName}';
        _classLabel = '${d['class_label'] ?? ''}';
        _sessionLabel = '${d['session_label'] ?? ''}';
        _termLabel = '${d['term_label'] ?? ''}';
        _subjects = ((d['subjects'] as List?) ?? []).map((e) => '$e').toList();
        _results = _maps(d['results']);
        _stats = Map<String, dynamic>.from((d['stats'] as Map?) ?? {});
        _gradeKey = _maps(d['grade_key']);
        _searched = true;
      });
      if (_results.isNotEmpty) {
        WidgetsBinding.instance.addPostFrameCallback((_) {
          final c = _tableKey.currentContext;
          if (c != null) Scrollable.ensureVisible(c, duration: const Duration(milliseconds: 350), curve: Curves.easeOut);
        });
      }
    } catch (e) {
      _toast(_friendly(e), error: true);
    } finally {
      if (mounted) setState(() => _generating = false);
    }
  }

  // ───────────────────────────── exports ─────────────────────────────
  String _ymd() {
    final n = DateTime.now();
    return '${n.year}${n.month.toString().padLeft(2, '0')}${n.day.toString().padLeft(2, '0')}';
  }

  String _today() {
    const m = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    final n = DateTime.now();
    return '${n.day.toString().padLeft(2, '0')} ${m[n.month - 1]} ${n.year}';
  }

  /// The built-in PDF font only knows Latin-1
  String _latin(String s) => s.runes.map((r) => r < 256 ? String.fromCharCode(r) : '?').join();

  String get _label => '$_classLabel | $_sessionLabel | $_termLabel';

  Future<void> _downloadExcel() async {
    if (_xlBusy || _results.isEmpty) return;
    setState(() => _xlBusy = true);
    try {
      final uri = Uri.parse(_apiUrl).replace(queryParameters: {
        'token': _token!,
        'action': 'export_excel',
        'class_id': '$_classId',
        'session_id': '$_sessionId',
        'term_id': '$_termId',
        if (_deptId > 0) 'department_id': '$_deptId',
      });
      final ok = await launchUrl(uri, mode: LaunchMode.externalApplication);
      if (!ok) _toast('Could not open the download.', error: true);
    } catch (e) {
      _toast('Excel download failed: ${_friendly(e)}', error: true);
    } finally {
      if (mounted) setState(() => _xlBusy = false);
    }
  }

  Future<void> _downloadPdf() async {
    if (_pdfBusy || _results.isEmpty) return;
    setState(() => _pdfBusy = true);
    try {
      final bytes = await _buildPdf();
      await Printing.sharePdf(bytes: bytes, filename: 'Cumulative_Results_${_ymd()}.pdf');
    } catch (e) {
      _toast('PDF generation failed: ${_friendly(e)}', error: true);
    } finally {
      if (mounted) setState(() => _pdfBusy = false);
    }
  }

  PdfColor _pc(int argb) => PdfColor.fromInt(argb);

  PdfColor _gradePdf(String g) {
    switch (g) {
      case 'A':
        return _pc(0xFF059669);
      case 'B':
        return _pc(0xFF2563EB);
      case 'C':
        return _pc(0xFFD97706);
      case 'D':
        return _pc(0xFFEA580C);
      case 'E':
        return _pc(0xFFDC2626);
      default:
        return _pc(0xFF64748B);
    }
  }

  Future<Uint8List> _buildPdf() async {
    final subN = _subjects.length;
    // paper size by subject count (same rule as the web page)
    final estMM = 110 + subN * 26;
    double wmm = 297, hmm = 210; // A4 landscape
    if (estMM > 594) {
      wmm = 841;
      hmm = 594; // A1
    } else if (estMM > 420) {
      wmm = 594;
      hmm = 420; // A2
    } else if (estMM > 297) {
      wmm = 420;
      hmm = 297; // A3
    }
    const mm = PdfPageFormat.mm;
    final format = PdfPageFormat(wmm * mm, hmm * mm);

    final usable = wmm - 10;
    final nameW = math.min(44.0, math.max(28.0, usable * 0.13));
    const snW = 7.0;
    final idW = math.min(22.0, math.max(14.0, usable * 0.06));
    const totW = 13.0, avgW = 22.0, posW = 10.0;
    final fixedW = snW + nameW + idW + totW + avgW + posW;
    final subW = subN > 0 ? math.max(13.0, (usable - fixedW) / subN) : 20.0;

    final fs = subN > 12 ? 6.0 : (subN > 8 ? 7.0 : 8.0);
    final hfs = subN > 12 ? 5.5 : 6.5;
    final pad = subN > 12 ? 1.2 : 1.8;

    final widths = <int, pw.TableColumnWidth>{
      0: pw.FixedColumnWidth(snW * mm),
      1: pw.FixedColumnWidth(nameW * mm),
      2: pw.FixedColumnWidth(idW * mm),
    };
    for (var s = 0; s < subN; s++) {
      widths[3 + s] = pw.FixedColumnWidth(subW * mm);
    }
    widths[3 + subN] = pw.FixedColumnWidth(totW * mm);
    widths[4 + subN] = pw.FixedColumnWidth(avgW * mm);
    widths[5 + subN] = pw.FixedColumnWidth(posW * mm);

    pw.Widget cell(String t, {double? size, PdfColor? color, bool bold = false, pw.TextAlign align = pw.TextAlign.center}) => pw.Padding(
          padding: pw.EdgeInsets.all(pad * mm),
          child: pw.Text(
            _latin(t),
            textAlign: align,
            style: pw.TextStyle(fontSize: size ?? fs, color: color ?? _pc(0xFF0F172A), fontWeight: bold ? pw.FontWeight.bold : pw.FontWeight.normal),
          ),
        );

    final head = pw.TableRow(
      repeat: true,
      decoration: pw.BoxDecoration(color: _pc(0xFF0F1F3D)),
      children: [
        cell('#', size: hfs, color: _pc(0xFFC8D7F0), bold: true),
        cell('Student Name', size: hfs, color: _pc(0xFFC8D7F0), bold: true),
        cell('ID No.', size: hfs, color: _pc(0xFFC8D7F0), bold: true),
        for (final s in _subjects) cell(s, size: hfs, color: _pc(0xFFC8D7F0), bold: true),
        cell('Total', size: hfs, color: _pc(0xFFC8D7F0), bold: true),
        cell('Average', size: hfs, color: _pc(0xFFC8D7F0), bold: true),
        cell('Pos.', size: hfs, color: _pc(0xFFC8D7F0), bold: true),
      ],
    );

    final body = <pw.TableRow>[];
    for (var i = 0; i < _results.length; i++) {
      final r = _results[i];
      final scores = (r['scores'] as List?) ?? [];
      final pos = _int(r['position']);
      PdfColor? posFill;
      PdfColor posText = _pc(0xFF0F172A);
      var posBold = false;
      if (pos == 1) {
        posFill = _pc(0xFFFEF3C7);
        posText = _pc(0xFF78350F);
        posBold = true;
      } else if (pos == 2) {
        posFill = _pc(0xFFF1F5F9);
        posText = _pc(0xFF1E293B);
        posBold = true;
      } else if (pos == 3) {
        posFill = _pc(0xFFFFF7ED);
        posText = _pc(0xFF7C2D12);
        posBold = true;
      }
      body.add(pw.TableRow(
        decoration: pw.BoxDecoration(color: i.isOdd ? _pc(0xFFF8FAFC) : PdfColors.white),
        children: [
          cell('${i + 1}'),
          cell('${r['fullname']}', align: pw.TextAlign.left),
          cell('${r['idnumber']}'),
          for (var s = 0; s < subN; s++)
            () {
              final sc = s < scores.length ? scores[s] : null;
              if (sc == null) return cell('-', color: _pc(0xFF94A3B8));
              final g = '${sc['grade']}';
              return cell('${_n(sc['score'])}/60 (${_n(sc['percentage'])}%) $g', color: _gradePdf(g), bold: true);
            }(),
          cell(_n(r['total'])),
          cell('${_n(r['average'])} (${r['avg_grade']})'),
          pw.Container(
            color: posFill,
            child: cell('$pos', color: posText, bold: posBold),
          ),
        ],
      ));
    }

    final doc = pw.Document();
    doc.addPage(pw.MultiPage(
      pageFormat: format,
      margin: pw.EdgeInsets.fromLTRB(5 * mm, 0, 5 * mm, 10 * mm),
      header: (ctx) => ctx.pageNumber == 1
          ? pw.Container(
              width: double.infinity,
              color: _pc(0xFF0A1628),
              margin: pw.EdgeInsets.only(bottom: 3 * mm),
              padding: pw.EdgeInsets.symmetric(vertical: 4 * mm),
              child: pw.Column(children: [
                pw.Text(_latin(_schoolName), style: pw.TextStyle(fontSize: 15, fontWeight: pw.FontWeight.bold, color: PdfColors.white)),
                pw.SizedBox(height: 2 * mm),
                pw.Text(_latin('Cumulative Result Sheet  -  $_label'), style: pw.TextStyle(fontSize: 8.5, color: _pc(0xFFB4C8E6))),
                pw.SizedBox(height: 1 * mm),
                pw.Text('Generated: ${_today()}', style: pw.TextStyle(fontSize: 8.5, color: _pc(0xFFB4C8E6))),
              ]),
            )
          : pw.SizedBox(height: 5 * mm),
      footer: (ctx) => pw.Row(mainAxisAlignment: pw.MainAxisAlignment.spaceBetween, children: [
        pw.Text(_latin('$_schoolName  |  $_label'), style: pw.TextStyle(fontSize: 7, color: _pc(0xFF94A3B8))),
        pw.Text('Page ${ctx.pageNumber} of ${ctx.pagesCount}', style: pw.TextStyle(fontSize: 7, color: _pc(0xFF94A3B8))),
      ]),
      build: (ctx) => [
        pw.Table(
          columnWidths: widths,
          defaultVerticalAlignment: pw.TableCellVerticalAlignment.middle,
          border: pw.TableBorder.all(color: _pc(0xFFE2E8F0), width: 0.18),
          children: [head, ...body],
        ),
      ],
    ));
    return doc.save();
  }

  // ───────────────────────────── BUILD ─────────────────────────────
  @override
  Widget build(BuildContext context) {
    return Theme(
      data: _lightTheme(),
      child: Scaffold(
        backgroundColor: _bg,
        appBar: AppBar(
          backgroundColor: Colors.white,
          surfaceTintColor: Colors.transparent,
          foregroundColor: _text,
          elevation: 0,
          title: const Text('Cumulative Results', style: TextStyle(fontWeight: FontWeight.w800)),
          actions: [IconButton(tooltip: 'Refresh', onPressed: _init, icon: const Icon(Icons.refresh))],
        ),
        body: _loadingData
            ? const Center(child: CircularProgressIndicator(color: _blue))
            : _dataError != null
                ? Center(
                    child: Padding(
                      padding: const EdgeInsets.all(24),
                      child: Column(mainAxisSize: MainAxisSize.min, children: [
                        const Icon(Icons.error_outline, color: Color(0xFFDC2626), size: 44),
                        const SizedBox(height: 10),
                        Text(_dataError!, textAlign: TextAlign.center, style: const TextStyle(color: Color(0xFFDC2626))),
                        const SizedBox(height: 14),
                        ElevatedButton.icon(
                          style: ElevatedButton.styleFrom(backgroundColor: _navy, foregroundColor: Colors.white),
                          onPressed: _init,
                          icon: const Icon(Icons.refresh),
                          label: const Text('Retry'),
                        ),
                      ]),
                    ),
                  )
                : SingleChildScrollView(
                    controller: _scroll,
                    padding: const EdgeInsets.fromLTRB(14, 16, 14, 70),
                    child: Center(
                      child: ConstrainedBox(
                        constraints: const BoxConstraints(maxWidth: 1600),
                        child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
                          _schoolCard(),
                          const SizedBox(height: 22),
                          _filterCard(),
                          const SizedBox(height: 22),
                          if (_results.isNotEmpty) ...[
                            _statsRow(),
                            const SizedBox(height: 22),
                            _tableSection(),
                          ] else if (_searched)
                            _emptyState(),
                        ]),
                      ),
                    ),
                  ),
      ),
    );
  }

  // ---------------------------- school card ----------------------------
  Widget _schoolCard() {
    return ClipRRect(
      borderRadius: BorderRadius.circular(16),
      child: Container(
        color: _navy,
        child: Stack(children: [
          Positioned(
            top: -60,
            right: -60,
            child: Container(width: 260, height: 260, decoration: BoxDecoration(color: const Color(0xFF2563EB).withOpacity(0.25), shape: BoxShape.circle)),
          ),
          Positioned(
            bottom: -40,
            left: 120,
            child: Container(width: 180, height: 180, decoration: BoxDecoration(color: const Color(0xFFF59E0B).withOpacity(0.07), shape: BoxShape.circle)),
          ),
          LayoutBuilder(builder: (context, c) {
            final narrow = c.maxWidth < 620;
            final titleBlock = Column(
              crossAxisAlignment: narrow ? CrossAxisAlignment.center : CrossAxisAlignment.start,
              children: [
                Text(
                  _schoolName,
                  textAlign: narrow ? TextAlign.center : TextAlign.left,
                  style: TextStyle(
                    fontFamily: 'serif',
                    fontFamilyFallback: const ['Georgia', 'Times New Roman'],
                    fontSize: narrow ? 22 : 28,
                    fontWeight: FontWeight.w700,
                    color: Colors.white,
                    height: 1.2,
                  ),
                ),
                const SizedBox(height: 4),
                Text('ACADEMIC PERFORMANCE PORTAL',
                    style: TextStyle(fontSize: 13, color: Colors.white.withOpacity(0.55), fontWeight: FontWeight.w500, letterSpacing: 0.6)),
              ],
            );
            final badge = Container(
              padding: const EdgeInsets.symmetric(horizontal: 18, vertical: 8),
              decoration: BoxDecoration(
                color: Colors.white.withOpacity(0.08),
                border: Border.all(color: Colors.white.withOpacity(0.15)),
                borderRadius: BorderRadius.circular(40),
              ),
              child: Row(mainAxisSize: MainAxisSize.min, children: [
                Icon(Icons.receipt_long, size: 14, color: Colors.white.withOpacity(0.7)),
                const SizedBox(width: 6),
                Text('CUMULATIVE RESULT SHEET',
                    style: TextStyle(color: Colors.white.withOpacity(0.8), fontSize: 12, fontWeight: FontWeight.w600, letterSpacing: 0.5)),
              ]),
            );
            return Padding(
              padding: EdgeInsets.symmetric(horizontal: narrow ? 24 : 36, vertical: narrow ? 24 : 32),
              child: narrow
                  ? Column(children: [titleBlock, const SizedBox(height: 16), badge])
                  : Row(children: [Expanded(child: titleBlock), const SizedBox(width: 16), badge]),
            );
          }),
        ]),
      ),
    );
  }

  // ---------------------------- filters ----------------------------
  InputDecoration _selectDec() => InputDecoration(
        isDense: true,
        filled: true,
        fillColor: _bg,
        contentPadding: const EdgeInsets.symmetric(horizontal: 14, vertical: 14),
        enabledBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(10), borderSide: const BorderSide(color: _border, width: 1.5)),
        focusedBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(10), borderSide: const BorderSide(color: _blue, width: 1.5)),
      );

  Widget _fg(IconData icon, String label, Widget field) => Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Padding(
          padding: const EdgeInsets.only(bottom: 6),
          child: Row(children: [
            Icon(icon, size: 13, color: _text2.withOpacity(0.6)),
            const SizedBox(width: 4),
            Text(label.toUpperCase(), style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w700, color: _text2, letterSpacing: 0.6)),
          ]),
        ),
        field,
      ]);

  Widget _drop(String placeholder, int? value, List<Map<String, dynamic>> items, String idKey, String nameKey, ValueChanged<int?> onChanged) {
    final has = items.any((m) => _int(m[idKey]) == value);
    return DropdownButtonFormField<int>(
      value: has ? value : null,
      isExpanded: true,
      decoration: _selectDec(),
      style: _fieldStyle,
      dropdownColor: Colors.white,
      menuMaxHeight: 320,
      icon: const Icon(Icons.keyboard_arrow_down, color: _muted),
      hint: Text(placeholder, style: const TextStyle(color: _text2, fontSize: 14)),
      items: [for (final m in items) DropdownMenuItem(value: _int(m[idKey]), child: Text('${m[nameKey]}', overflow: TextOverflow.ellipsis))],
      onChanged: onChanged,
    );
  }

  Widget _filterCard() {
    return Container(
      padding: const EdgeInsets.all(24),
      decoration: BoxDecoration(color: Colors.white, borderRadius: BorderRadius.circular(16), border: Border.all(color: _border), boxShadow: _shadow),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          Container(
            width: 36,
            height: 36,
            decoration: BoxDecoration(color: _sky, borderRadius: BorderRadius.circular(10)),
            child: const Icon(Icons.tune, size: 16, color: _blue),
          ),
          const SizedBox(width: 10),
          const Text('Generate Result Sheet', style: TextStyle(fontSize: 16, fontWeight: FontWeight.w700)),
        ]),
        const SizedBox(height: 20),
        LayoutBuilder(builder: (context, c) {
          final cols = c.maxWidth >= 900 ? 4 : (c.maxWidth >= 480 ? 2 : 1);
          final w = (c.maxWidth - 16 * (cols - 1)) / cols;
          Widget sized(Widget child) => SizedBox(width: w, child: child);
          return Wrap(spacing: 16, runSpacing: 16, children: [
            sized(_fg(Icons.class_outlined, 'Class', _drop('— Select Class —', _classId, _classes, 'class_id', 'class_name', (v) => setState(() => _classId = v)))),
            sized(_fg(Icons.calendar_month, 'Session', _drop('— Select Session —', _sessionId, _sessions, 'id', 'session_name', (v) => setState(() => _sessionId = v)))),
            sized(_fg(Icons.bookmark_outline, 'Term', _drop('— Select Term —', _termId, _terms, 'id', 'term_name', (v) => setState(() => _termId = v)))),
            sized(_fg(
              Icons.apartment,
              'Department',
              DropdownButtonFormField<int>(
                value: (_deptId == 0 || _departments.any((d) => _int(d['id']) == _deptId)) ? _deptId : 0,
                isExpanded: true,
                decoration: _selectDec(),
                style: _fieldStyle,
                dropdownColor: Colors.white,
                menuMaxHeight: 320,
                icon: const Icon(Icons.keyboard_arrow_down, color: _muted),
                items: [
                  const DropdownMenuItem(value: 0, child: Text('All Departments')),
                  for (final d in _departments) DropdownMenuItem(value: _int(d['id']), child: Text('${d['department_name']}', overflow: TextOverflow.ellipsis)),
                ],
                onChanged: (v) => setState(() => _deptId = v ?? 0),
              ),
            )),
          ]);
        }),
        const SizedBox(height: 20),
        ElevatedButton.icon(
          onPressed: _generating ? null : _generate,
          style: ElevatedButton.styleFrom(
            backgroundColor: _navy,
            foregroundColor: Colors.white,
            disabledBackgroundColor: _navy.withOpacity(0.6),
            disabledForegroundColor: Colors.white70,
            padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 14),
            shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(10)),
          ),
          icon: _generating
              ? const SizedBox(width: 16, height: 16, child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white))
              : const Icon(Icons.table_chart, size: 18),
          label: Text(_generating ? 'Generating…' : 'Generate Results', style: const TextStyle(fontWeight: FontWeight.w700, fontSize: 14)),
        ),
      ]),
    );
  }

  // ---------------------------- stats ----------------------------
  Widget _statsRow() {
    final cards = [
      (Icons.groups, const Color(0xFFEFF6FF), const Color(0xFF2563EB), '${_int(_stats['total_students'])}', 'Total Students'),
      (Icons.menu_book, const Color(0xFFEEF2FF), const Color(0xFF4F46E5), '${_int(_stats['subject_count'])}', 'Subjects'),
      (Icons.check_circle, const Color(0xFFECFDF5), const Color(0xFF059669), '${_int(_stats['pass_rate'])}%', 'Pass Rate'),
      (Icons.show_chart, const Color(0xFFFFFBEB), const Color(0xFFD97706), _n(_stats['class_average']), 'Class Average'),
    ];
    return LayoutBuilder(builder: (context, c) {
      const gap = 16.0;
      final cols = c.maxWidth >= 720 ? 4 : 2;
      final w = (c.maxWidth - gap * (cols - 1)) / cols;
      return Wrap(spacing: gap, runSpacing: gap, children: [
        for (final s in cards)
          SizedBox(
            width: w,
            child: Container(
              padding: const EdgeInsets.fromLTRB(18, 20, 18, 20),
              decoration: BoxDecoration(color: Colors.white, borderRadius: BorderRadius.circular(16), border: Border.all(color: _border), boxShadow: _shadow),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Container(
                  width: 38,
                  height: 38,
                  decoration: BoxDecoration(color: s.$2, borderRadius: BorderRadius.circular(10)),
                  child: Icon(s.$1, size: 17, color: s.$3),
                ),
                const SizedBox(height: 10),
                Text(s.$4, style: const TextStyle(fontSize: 26, fontWeight: FontWeight.w800, height: 1)),
                const SizedBox(height: 6),
                Text(s.$5, style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w600, color: _text2)),
              ]),
            ),
          ),
      ]);
    });
  }

  // ---------------------------- result table ----------------------------
  Widget _tableSection() {
    final students = _int(_stats['total_students']);
    final subN = _subjects.length;
    return Container(
      key: _tableKey,
      decoration: BoxDecoration(color: Colors.white, borderRadius: BorderRadius.circular(16), border: Border.all(color: _border), boxShadow: _shadow),
      clipBehavior: Clip.antiAlias,
      child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        // header band
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 22, vertical: 18),
          decoration: const BoxDecoration(gradient: LinearGradient(begin: Alignment.topLeft, end: Alignment.bottomRight, colors: [_navy, _navy2])),
          child: Wrap(
            alignment: WrapAlignment.spaceBetween,
            crossAxisAlignment: WrapCrossAlignment.center,
            spacing: 14,
            runSpacing: 12,
            children: [
              Row(mainAxisSize: MainAxisSize.min, children: [
                Icon(Icons.list_alt, size: 16, color: Colors.white.withOpacity(0.7)),
                const SizedBox(width: 10),
                ConstrainedBox(
                  constraints: const BoxConstraints(maxWidth: 520),
                  child: Text('$_classLabel — $_sessionLabel, $_termLabel',
                      style: const TextStyle(color: Colors.white, fontSize: 15, fontWeight: FontWeight.w700)),
                ),
              ]),
              Text('$students students • $subN subjects', style: TextStyle(fontSize: 12, color: Colors.white.withOpacity(0.55), fontWeight: FontWeight.w500)),
              Row(mainAxisSize: MainAxisSize.min, children: [
                _dlBtn(Icons.picture_as_pdf, _pdfBusy ? 'Building PDF…' : 'PDF', const Color(0xFFDC2626), _pdfBusy ? null : _downloadPdf),
                const SizedBox(width: 8),
                _dlBtn(Icons.table_view, _xlBusy ? 'Opening…' : 'Excel', const Color(0xFF059669), _xlBusy ? null : _downloadExcel),
              ]),
            ],
          ),
        ),
        // scroll hint (phones)
        LayoutBuilder(builder: (context, c) {
          if (c.maxWidth >= 768) return const SizedBox.shrink();
          return Container(
            padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
            decoration: const BoxDecoration(color: Color(0xFFFFFBEB), border: Border(bottom: BorderSide(color: Color(0xFFFDE68A)))),
            child: Row(children: [
              const Icon(Icons.swap_horiz, size: 16, color: Color(0xFFD97706)),
              const SizedBox(width: 6),
              Expanded(
                child: Text('Scroll horizontally to see all $subN subjects',
                    style: const TextStyle(fontSize: 12, color: Color(0xFF92400E), fontWeight: FontWeight.w600)),
              ),
            ]),
          );
        }),
        _grid(),
        _legend(),
      ]),
    );
  }

  Widget _dlBtn(IconData icon, String label, Color accent, VoidCallback? onTap) => Opacity(
        opacity: onTap == null ? 0.6 : 1,
        child: InkWell(
          borderRadius: BorderRadius.circular(8),
          onTap: onTap,
          child: Container(
            padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
            decoration: BoxDecoration(
              color: Colors.white.withOpacity(0.07),
              border: Border.all(color: accent.withOpacity(0.5)),
              borderRadius: BorderRadius.circular(8),
            ),
            child: Row(mainAxisSize: MainAxisSize.min, children: [
              Icon(icon, size: 14, color: Colors.white),
              const SizedBox(width: 7),
              Text(label, style: const TextStyle(color: Colors.white, fontSize: 12, fontWeight: FontWeight.w700)),
            ]),
          ),
        ),
      );

  static const double _headH = 46;
  static const double _rowH = 80;
  static const double _snW = 52;
  static const double _nameW = 170;
  static const double _idW = 110;
  static const double _subW = 130;
  static const double _totW = 90;
  static const double _avgW = 100;
  static const double _posW = 80;

  Widget _th(String text, double w, {Color? bg, Gradient? gradient, bool left = false, String? tooltip}) {
    Widget t = Text(
      text.toUpperCase(),
      maxLines: 1,
      overflow: TextOverflow.ellipsis,
      textAlign: left ? TextAlign.left : TextAlign.center,
      style: TextStyle(fontSize: 11.5, fontWeight: FontWeight.w700, color: Colors.white.withOpacity(0.85), letterSpacing: 0.4),
    );
    if (tooltip != null) t = Tooltip(message: tooltip, child: t);
    return Container(
      width: w,
      height: _headH,
      padding: const EdgeInsets.symmetric(horizontal: 14),
      alignment: left ? Alignment.centerLeft : Alignment.center,
      decoration: BoxDecoration(
        color: bg,
        gradient: gradient,
        border: Border(right: BorderSide(color: Colors.white.withOpacity(0.07))),
      ),
      child: t,
    );
  }

  Widget _grid() {
    const subjGrad = LinearGradient(colors: [Color(0xFF0F1F3D), Color(0xFF1B3268)]);

    // ---- left (sticky): # and name ----
    final left = Column(children: [
      Row(children: [
        _th('#', _snW, bg: const Color(0xFF0A1628)),
        _th('Student Name', _nameW, bg: const Color(0xFF0E1B36), left: true),
      ]),
      for (var i = 0; i < _results.length; i++) _leftRow(i),
    ]);

    // ---- right (scrolls): ID, subjects, total, avg, pos ----
    final right = Column(children: [
      Row(children: [
        _th('ID No.', _idW, bg: const Color(0xFF0E1B36)),
        for (final s in _subjects) _th(s.length > 14 ? '${s.substring(0, 13)}…' : s, _subW, gradient: subjGrad, tooltip: s),
        _th('Total', _totW, bg: const Color(0xFF1B3268)),
        _th('Avg', _avgW, bg: const Color(0xFF1B3268)),
        _th('Pos.', _posW, bg: const Color(0xFF0A1628)),
      ]),
      for (var i = 0; i < _results.length; i++) _rightRow(i),
    ]);

    return Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
      Container(
        decoration: BoxDecoration(boxShadow: [BoxShadow(color: Colors.black.withOpacity(0.06), blurRadius: 8, offset: const Offset(3, 0))]),
        child: left,
      ),
      Expanded(
        child: SingleChildScrollView(
          scrollDirection: Axis.horizontal,
          child: right,
        ),
      ),
    ]);
  }

  Color _zebra(int i) => i.isOdd ? const Color(0xFFF8FAFC) : Colors.white;

  Widget _leftRow(int i) {
    final r = _results[i];
    return Row(children: [
      Container(
        width: _snW,
        height: _rowH,
        alignment: Alignment.center,
        decoration: BoxDecoration(
          color: i.isOdd ? const Color(0xFFE8EFFF) : const Color(0xFFF0F4FF),
          border: const Border(bottom: BorderSide(color: _border), right: BorderSide(color: Color(0xFFE0E7FF))),
        ),
        child: Text('${i + 1}', style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w800, color: _blue)),
      ),
      Container(
        width: _nameW,
        height: _rowH,
        padding: const EdgeInsets.symmetric(horizontal: 14),
        alignment: Alignment.centerLeft,
        decoration: BoxDecoration(
          color: _zebra(i),
          border: const Border(bottom: BorderSide(color: _border), right: BorderSide(color: _border)),
        ),
        child: Text('${r['fullname']}',
            maxLines: 2, overflow: TextOverflow.ellipsis, style: const TextStyle(fontWeight: FontWeight.w700, color: _navy, fontSize: 13.5)),
      ),
    ]);
  }

  Widget _plain(double w, Widget child, int i) => Container(
        width: w,
        height: _rowH,
        alignment: Alignment.center,
        decoration: BoxDecoration(
          color: _zebra(i),
          border: const Border(bottom: BorderSide(color: _border), right: BorderSide(color: Color(0xFFF1F5F9))),
        ),
        child: child,
      );

  Widget _gradeChip(String g, {double size = 22}) {
    final c = _grades[g] ?? _grades['F']!;
    return Container(
      width: size,
      height: size,
      alignment: Alignment.center,
      decoration: BoxDecoration(color: c.bg, borderRadius: BorderRadius.circular(6), border: Border.all(color: c.border)),
      child: Text(g, style: TextStyle(fontSize: 10, fontWeight: FontWeight.w800, color: c.fg)),
    );
  }

  Widget _rightRow(int i) {
    final r = _results[i];
    final scores = (r['scores'] as List?) ?? [];
    final avgGrade = '${r['avg_grade']}';
    final avg = double.tryParse('${r['average']}') ?? 0;
    final frac = math.min(1.0, avg / 60);
    final fill = _fills[avgGrade] ?? _fills['F']!;
    final pos = _int(r['position']);

    return Row(children: [
      _plain(_idW, Text('${r['idnumber']}', style: const TextStyle(fontSize: 12, color: _text2, fontWeight: FontWeight.w500)), i),
      for (var s = 0; s < _subjects.length; s++)
        _plain(
          _subW,
          () {
            final sc = s < scores.length ? scores[s] : null;
            if (sc == null) return const Text('—', style: TextStyle(color: _muted, fontSize: 18));
            return Column(mainAxisAlignment: MainAxisAlignment.center, children: [
              Text.rich(TextSpan(children: [
                TextSpan(text: _n(sc['score']), style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w800)),
                const TextSpan(text: '/60', style: TextStyle(fontSize: 9, fontWeight: FontWeight.w500, color: _muted)),
              ])),
              const SizedBox(height: 2),
              Text('${_n(sc['percentage'])}%', style: const TextStyle(fontSize: 10.5, color: _text2, fontWeight: FontWeight.w500)),
              const SizedBox(height: 2),
              _gradeChip('${sc['grade']}'),
            ]);
          }(),
          i,
        ),
      _plain(_totW, Text(_n(r['total']), style: const TextStyle(fontSize: 14, fontWeight: FontWeight.w800, color: _navy)), i),
      _plain(
        _avgW,
        Column(mainAxisAlignment: MainAxisAlignment.center, children: [
          Text(_n(r['average']), style: const TextStyle(fontSize: 15, fontWeight: FontWeight.w800, color: _blue2)),
          const SizedBox(height: 3),
          Container(
            width: 60,
            height: 5,
            decoration: BoxDecoration(color: _border, borderRadius: BorderRadius.circular(3)),
            alignment: Alignment.centerLeft,
            child: FractionallySizedBox(
              widthFactor: frac,
              child: Container(decoration: BoxDecoration(gradient: LinearGradient(colors: fill), borderRadius: BorderRadius.circular(3))),
            ),
          ),
        ]),
        i,
      ),
      _plain(_posW, _posBadge(pos), i),
    ]);
  }

  Widget _posBadge(int pos) {
    Gradient? g;
    Color fg = _text2;
    Color? solid;
    double size = 12;
    if (pos == 1) {
      g = const LinearGradient(begin: Alignment.topLeft, end: Alignment.bottomRight, colors: [Color(0xFFF59E0B), Color(0xFFFBBF24)]);
      fg = const Color(0xFF78350F);
    } else if (pos == 2) {
      g = const LinearGradient(begin: Alignment.topLeft, end: Alignment.bottomRight, colors: [Color(0xFF94A3B8), Color(0xFFCBD5E1)]);
      fg = const Color(0xFF1E293B);
    } else if (pos == 3) {
      g = const LinearGradient(begin: Alignment.topLeft, end: Alignment.bottomRight, colors: [Color(0xFFCD7F32), Color(0xFFD97706)]);
      fg = Colors.white;
    } else {
      solid = const Color(0xFFF1F5F9);
      size = 11;
    }
    return Container(
      width: 32,
      height: 32,
      alignment: Alignment.center,
      decoration: BoxDecoration(color: solid, gradient: g, shape: BoxShape.circle),
      child: Text('$pos', style: TextStyle(fontSize: size, fontWeight: FontWeight.w800, color: fg)),
    );
  }

  // ---------------------------- legend / empty ----------------------------
  Widget _legend() {
    final key = _gradeKey.isNotEmpty
        ? _gradeKey
        : [
            {'grade': 'A', 'range': '70–100%'},
            {'grade': 'B', 'range': '60–69%'},
            {'grade': 'C', 'range': '50–59%'},
            {'grade': 'D', 'range': '45–49%'},
            {'grade': 'E', 'range': '40–44%'},
            {'grade': 'F', 'range': '0–39%'},
          ];
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 16),
      decoration: const BoxDecoration(color: Color(0xFFFAFBFD), border: Border(top: BorderSide(color: _border))),
      child: Wrap(spacing: 14, runSpacing: 10, crossAxisAlignment: WrapCrossAlignment.center, children: [
        const Text('GRADE KEY:', style: TextStyle(fontSize: 11, fontWeight: FontWeight.w800, letterSpacing: 0.6, color: _muted)),
        for (final k in key)
          Row(mainAxisSize: MainAxisSize.min, children: [
            _gradeChip('${k['grade']}'),
            const SizedBox(width: 5),
            Text('${k['range']}', style: const TextStyle(fontSize: 11.5, fontWeight: FontWeight.w600, color: _text2)),
          ]),
      ]),
    );
  }

  Widget _emptyState() => Container(
        padding: const EdgeInsets.symmetric(vertical: 60, horizontal: 20),
        decoration: BoxDecoration(color: Colors.white, borderRadius: BorderRadius.circular(16), border: Border.all(color: _border), boxShadow: _shadow),
        child: Column(children: [
          Icon(Icons.inbox, size: 40, color: _text2.withOpacity(0.2)),
          const SizedBox(height: 14),
          const Text('No results found', style: TextStyle(fontSize: 17, fontWeight: FontWeight.w700)),
          const SizedBox(height: 6),
          const Text('No exam results match the selected class, session, and term.', textAlign: TextAlign.center, style: TextStyle(fontSize: 14, color: _text2)),
        ]),
      );
}
